INSERT INTO `nutritional_recipe` VALUES (1730862948642, '/static/2025-07-19/3bcdc6da3ff04dc7a65a82d292b40387.jpg', '土豆烧牛腩', '土豆烧牛腩是一道美味的家常菜，主要食材是牛腩和土豆。', '炖菜', '2214.8', '122.1', '150.3', '102.7', '牛肉（腹部肉）(牛腩) 500g\n马铃薯【土豆、洋芋】 300g\n辣椒（红、尖、干） 20g\n大蒜【蒜头】 30g\n洋葱（紫皮，脱水） 50g\n黄姜 30g\n', '食用油适量\n盐适量\n酱油两勺\n耗油一勺\n料酒适量\n冰糖5颗\n清水适量', '牛腩洗净切块用清水侵泡10分钟，土豆去皮切块备用。\n牛腩冷水下锅，倒入料酒，水开撇去浮沫，然后捞出备用。\n锅中倒入适量的食用油，加热后放入洋葱、生姜、大蒜、干辣椒煸炒出香味。\n加入牛腩煸炒至表面微黄，然后加入酱油、耗油翻炒均匀。\n加入适量的水（最好是开水），加入土豆、冰糖、盐，大火烧开后转小火炖煮。\n炖煮约 1 小时后，待牛腩炖熟，土豆软糯，开大火收汁即可。', '可以根据个人口味调整盐和酱油的量。\n如果用高压锅，上汽之后小火30分钟即可', '2024-11-06 11:15:49', '2025-08-16 11:40:05');
INSERT INTO `nutritional_recipe` VALUES (1730863203331, '/static/2025-07-19/a68d8bef30914c7aac1e72311c6ffa48.png', '皮蛋豆腐', '皮蛋豆腐是一道简单美味的凉菜，主要材料是皮蛋和嫩豆腐。', '凉菜', '385.0', '14.1', '21.6', '33.7', '松花蛋（鸭蛋）(皮蛋) 150g\n内酯豆腐 200g\n', '盐少许\n鸡精少许\n酱油一勺\n耗油一勺\n香油半勺\n辣椒油适量', '嫩豆腐用开水烫一下，捞出沥干水分，切成块状。\n皮蛋去壳，清洗干净后切成小块【可以小煮一下】。\n用大碗将豆腐放中间，周边摆上皮蛋。\n另取一小碗，碗里放酱油、耗油、葱末、姜末、辣椒面、小米辣，将热油浇给~，\n然后再倒香油、鸡精、盐，搅拌均匀，淋于大碗中。\n最后撒上适量的葱花，上菜~', '根据个人口味加入适量的酱油、香油和辣椒油。\n放入冰箱冷藏 30 分钟左右，风味更佳。', '2024-11-06 11:20:03', '2025-12-19 07:18:05');
INSERT INTO `nutritional_recipe` VALUES (1730863584896, '/static/2025-07-19/1a9d3583637a4c90b3a819e91705aa4a.jpeg', '鸡翅鸡爪煲', '鸡翅鸡爪煲是一道广受欢迎的家常菜，主要材料是鸡翅和鸡爪，通常会加入香料和调味料慢炖至入味', '煲菜', '1550', '21', '97', '137', '鸡翅 500 克\n鸡爪 500 克\n洋葱半个\n生姜几片\n香叶两片\n桂皮、花椒少许\n八角两个\n', '生抽两勺\n耗油两勺\n老抽一勺\n甜面酱两勺\n黄豆酱一勺\n鸡精一勺\n胡椒粉一勺\n白砂糖一勺\n盐少许\n清水适量\n', '鸡翅和鸡爪洗净，生姜切片，大蒜拍碎备用。\n鸡翅改刀、鸡爪去掉指甲盖。\n鸡翅、鸡爪冷水下锅，加葱、姜、料酒，水开撇去浮沫，捞出备用。\n锅里热油，放洋葱、一勺红油豆瓣酱、桂皮、八角、香叶、花椒炒香，再倒入鸡翅鸡爪翻炒均匀。\n倒入【调料区的料汁】，翻炒均匀。加入适量水淹没食材。\n大火烧开，转小火炖煮20分钟。\n加入配菜，再炖煮15分钟。\n根据个人口味调整盐的量，可以适当加一些鸡精或味精提鲜。\n最后撒上葱花上菜', '可以放一些自己喜欢的配菜，比如玉米、土豆、各种丸子\n珐琅锅全程不用再加水，如果是其他铁锅、砂锅，中途看情况加水。', '2024-11-06 11:26:25', '2025-07-19 16:11:42');
INSERT INTO `nutritional_recipe` VALUES (1730873906184, '/static/2025-07-19/6261b0197e0b4747831cd6843334054b.jpeg', '清蒸鲈鱼', '清蒸鲈鱼是一道非常受欢迎的粤菜，以其清淡、鲜美而著称', '粤菜', '551.9', '1.6', '17.8', '96.6', '鲈鱼 300g\n仔姜【嫩姜】 20g\n小葱【葱】 10g\n', '盐适量\n生抽或蒸鱼豉油适量\n食用油适量', '将鲈鱼清洗干净，在鱼身两侧各划几刀以便入味。\n盆里倒入清水【足够淹没鱼】，撒盐、姜片、葱段、料酒，搅拌几下，放入鲈鱼，侵泡15分钟。\n捞出鲈鱼，将盆里的姜片、葱段捞出放于鲈鱼腹部以及花刀处。\n锅里倒入足量清水，水开后放入鲈鱼，大火隔水蒸 8 至 10 分钟（根据鱼的大小调整时间），直到鱼熟透。\n在蒸好的鱼上均匀地倒入适量的生抽或蒸鱼豉油，再鱼身上放上葱丝、红椒丝。\n锅中倒入适量的食用油，加热至油热后，小心地浇在鱼身上，让香味充分释放。\n最后，撒上一一点葱花，上菜~', '懒人速成菜', '2024-11-06 14:18:26', '2025-12-19 06:51:51');
INSERT INTO `nutritional_recipe` VALUES (1730874263750, '/static/2025-07-19/f4e0fed3900248a1be9740600b151c32.jpeg', '回锅肉', '回锅肉是四川传统菜肴之一，口味独特、香气四溢，主要材料包括五花肉和蒜苗', '川菜', '1226.2', '39.0', '101.7', '51.6', ' 猪肉（硬五花）            250g\n辣椒（红、尖、干） 30g\n蒜苗【青蒜】 100g\n大葱 30g\n黄姜 20g\n', '豆瓣酱一勺\n豆豉两勺\n料酒适量\n白糖半勺\n花椒粉少许\n食用油适量', '五花肉洗净，放入锅中加水、料酒、姜片煮至七成熟，捞出切片备用。\n蒜苗、青红椒洗净切段，姜蒜切片备用。\n锅中倒入适量的食用油，加热后放入姜蒜片爆香。\n加入豆瓣酱和豆豉炒出红油。\n放入切好的五花肉片，快速翻炒使肉片均匀裹上豆瓣酱。\n加入青红椒和蒜苗，继续翻炒。\n根据口味加入适量的白糖、花椒粉调味。\n炒至蒜苗断生，肉片出油即可。', '不爱吃肥肉的话，五花肉可以煸干一些。会很香', '2024-11-06 14:24:24', '2025-08-16 11:40:32');
INSERT INTO `nutritional_recipe` VALUES (1730874336842, '/static/2025-07-19/e3bc8159659e4e08a478f10ab3ba4479.jpg', '肉末蒸蛋', '肉末蒸蛋是一道简单美味的家常菜，适合各个年龄段的人食用', '粤菜', '509.9', '4.9', '33.6', '47.3', '鸡蛋（白皮） 200g\n 猪肉（瘦）                100g\n小葱【葱】 10g\n', '香油适量\n食用油适量\n清水适量\n盐适量\n生抽适量\n白胡椒粉适量', '猪绞肉加入少许盐、生抽、白胡椒粉、葱花和香油，搅拌均匀腌制 10 分钟。\n鸡蛋打入碗中，加入 100 毫升清水，搅拌均匀。\n将蛋液过筛倒入深盘中，去除表面的泡沫。\n将腌好的肉泥铺在蛋液表面。\n放入蒸锅中，中火蒸 10 到 15 分钟，直到肉熟蛋凝固。\n蒸好后取出，表面撒上葱花，淋上适量的生抽和香油。', '小孩特爱吃', '2024-11-06 14:25:37', '2025-12-19 07:17:29');
INSERT INTO `nutritional_recipe` VALUES (1730875014738, '/static/2025-07-19/c4b26b6edfa64e03956327d6c2fc194a.jpg', '爆炒花蛤', '爆炒花蛤是一道美味的海鲜菜肴，口感鲜美，做法简单。', '家常菜', '286.6', '19.7', '4.7', '43.9', '蛤蜊（花蛤蜊） 250g\n小葱【葱】 10g\n黄姜 10g\n辣椒（红、尖、干） 10g\n', '豆瓣酱适量\n料酒适量\n生抽适量\n蚝油适量\n糖适量\n食用油适量', '花蛤洗净，用清水浸泡，让其吐净泥沙。\n青红椒去籽切条，葱切段，姜切丝，大蒜切片备用。\n锅中加水，放入花蛤煮至开口，捞出沥干水分。\n锅中倒入适量的食用油，加热后放入姜蒜片爆香。\n加入豆瓣酱炒出红油。\n放入青红椒条翻炒。\n加入料酒、生抽、蚝油和糖调味。\n最后放入花蛤快速翻炒，使花蛤均匀裹上酱汁。\n根据口味调整盐的量，撒上葱花炒匀即可出锅', '通过爆炒的方式快速烹饪花蛤，使其口感鲜嫩，味道丰富。这道菜肴的制作过程中，使用了豆瓣酱、生抽、蚝油等调味料，体现了中国菜肴调味的多样性。由于中国幅员辽阔，各地口味和烹饪技法差异较大，爆炒花蛤这样的菜肴可能融合了不同地区的烹饪特点，因此很难将其归入一个特定的菜系。它适合作为家庭餐桌上的美味佳肴，也常见于餐馆和小吃店', '2024-11-06 14:36:55', '2025-08-18 21:30:36');
INSERT INTO `nutritional_recipe` VALUES (1730875501078, '/static/2025-07-21/0196840c46634280a460cb0153fa821d.jpeg', '白灼菜心', '白灼菜心是一道简单却美味可口的粤菜，强调保持菜心的原味和营养。', '粤菜', '106.8', '19.7', '2.7', '7.9', '菜心 500 克\n葱丝少许油菜心 500g、大蒜【蒜头】 10g、辣椒（红、尖、干） 5g、', '生抽适量\n食用油适量\n盐适量', '菜心洗净，去除老叶和根部，用清水浸泡 10 分钟，然后沥干。\n锅中加水，放入适量的盐和食用油，大火烧开。\n将菜心放入沸水中焯烫 2 分钟左右【菜头先烫40秒】，直到菜心变绿且变软，捞出沥干。\n将焯烫好的菜心摆盘，淋上生抽。放上葱丝。\n最后淋上热油即可。\n', '选择新鲜的菜心是制作美味白灼菜心的关键，新鲜的菜心口感更加脆嫩。\n在焯烫菜心时加入少量的盐和食用油，可以使菜心保持绿色，更加鲜亮。\n焯烫菜心的时间不宜过长，否则菜心会变得过于软烂，失去脆嫩的口感。\n菜心含有丰富的维生素和纤维素，是一道非常健康的蔬菜。', '2024-11-06 14:45:01', '2025-08-14 15:40:50');
INSERT INTO `nutritional_recipe` VALUES (1765590478184, '/static/2025-12-14/749839bd2cc74935b2d26ef7f10fd2ed.jpg', '山楂排骨', '酸甜口味，喜欢醋的可以将山楂换成醋。', '川菜', '2836.1', '0.0', '268.0', '115.6', ' 猪小排（良杂猪）          500g\n', '生姜3片、八角2个、桂皮一小点、香叶2片、花椒20粒、冰糖8粒、山楂干两片[鲜山楂清洗去核两三个]、生抽一勺、老抽半勺、料酒[焯水用]、葱花[香葱]', '1.排骨清洗后冷水下锅，倒入料酒，水开两分钟捞出[中途记得要撇去浮沫]，冷水清洗后备用。\n2.热锅冷油、油热放入排骨、生姜、八角、桂皮、花椒、香叶，煸炒至排骨焦黄[两三分钟左右]，然后锅里加热水[高压锅没过食材多一点点，铁锅就再多一些水]，加入生抽、老抽、白糖、山楂。\n3.[铁锅]水开之后转小火，炖一个小时[期间不定时看一下，防止水干]。[高压锅]上气之后转小火，炖25分钟。\n4.最后去掉料渣[生姜、八角这些]，收汁、起锅装盘散葱花。', '铁锅炖煮的时候一定不要把水烧干了，不定时的去查看锅中情况。', '2025-12-13 01:47:58', '2025-12-14 10:20:17');
INSERT INTO `nutritional_recipe` VALUES (1765959544122, '/static/2025-12-17/dd0d55a5a5e84db4be74e0454fa1a60e.jpg', '咖喱土豆饭', '咖喱土豆饭是以土豆与米饭为核心食材，搭配咖喱粉或咖喱块调味制成的快餐类食品。其制作流程通常包含食材切丁、翻炒炝锅、加水焖煮、调味收汁等步骤，烹饪时长普遍控制在10至15分钟内。辅料可根据个人喜好增减，常见胡萝卜、洋葱、彩椒等蔬菜，部分做法会添加火腿或肉类提升风味。成品以米饭为基底，浇淋浓稠的咖喱土豆酱汁，表面常撒黑芝麻或搭配西兰花装饰。', '粤菜', '754.3', '136.1', '4.1', '51.4', '马铃薯【土豆、洋芋】 200g\n胡萝卜 200g\n洋葱（紫皮，脱水） 100g\n鸡胸脯肉 150g\n', '咖喱两块', '1.将土豆、胡萝卜、洋葱、鸡肉切成指甲盖大小的丁，备用。\n2.锅热倒油，油热放入鸡肉，煸炒变色，加入洋葱、土豆、胡萝卜，翻炒两分钟。\n3.加水没过食材，水开调至中火煮10分钟。\n4.调小火[也可以关火]后，锅中加入咖喱块搅拌均匀，咖喱块完全溶解后再小火炖煮5分钟至咖喱呈粘稠状。\n5.最后将煮好的咖喱浇在米饭上即可。', '正常加入咖喱块即可，无需加其他调味料。\n正常的咖喱应该稀稠适中，若太稀可多加热一会儿，太稠可适当加水。', '2025-12-17 08:19:04', '2025-12-17 08:25:31');
INSERT INTO `nutritional_recipe` VALUES (1766126572833, '', '木耳炒肉', '木耳炒肉的家常做法以‌木耳和猪肉为主料‌，通过快速炒制保留食材的鲜嫩口感，是一道操作简单、营养均衡的家常菜。', '家常菜', '358.9', '16.2', '14.5', '45.3', '木耳（水发）【黑木耳、云耳】 100g\n 猪肉（通脊，良杂猪）      200g\n辣椒（红、尖、干） 10g\n胡萝卜 20g\n黄姜 5g\n大蒜【蒜头】 5g\n小葱【葱】 5g\n', '盐、生抽、料酒、淀粉、蚝油、花椒', '1.木耳用冷水泡发3-4小时【鲜木耳洗净】，去除根部硬结后撕成小朵，沸水焯烫1分钟后捞出备用。\n2.猪肉切薄片或丝，用盐、料酒、淀粉抓匀腌制10分钟。\n3.热锅冷油，油热时放入姜蒜片、花椒爆香。\n4.下肉片快速滑炒至变色，盛出备用（防止肉质变老）。‌‌\n5.余油中倒入木耳和配菜（青红椒、胡萝卜）大火翻炒1-2分钟。‌‌\n6.肉片回锅，加生抽、蚝油、盐等调味，沿锅边淋少许水防粘，最后加入葱花翻炒均匀即可出锅。‌‌', '火候控制‌：全程大火快炒，总时长控制在5分钟内，确保木耳脆嫩、肉质鲜滑。‌‌\n防粘锅‌：使用“热锅凉油”法，炒制时分次加少量热水。‌‌\n‌风味调整‌：喜辣可加干辣椒或豆瓣酱；江浙地区可添加莴笋片增加爽脆感。‌‌\n', '2025-12-19 06:42:53', '2025-12-19 06:42:53');
INSERT INTO `nutritional_recipe` VALUES (1766385598583, '', '羊肉排骨萝卜汤', '羊肉排骨汤是一道以羊排为主料的滋补汤品，制作时需通过‌凉水焯水去血沫‌和‌慢火炖煮‌来确保汤色奶白、肉质鲜嫩无膻味，常见搭配包括白萝卜、胡萝卜等食材以提升风味和营养。‌‌', '家常菜', '772.7', '15.7', '22.6', '129.1', '羊肉（后腿、带骨） 500g\n白萝卜（鲜） 200g\n黄姜 30g\n大葱 30g\n', '白酒、盐、料酒', '1.将羊排剁成4-5厘米的块状，用清水浸泡30分钟以上（可加盐或淘米水）去除血水，减少腥味。‌‌\n2.羊排凉水下锅，加入姜片、葱段和料酒，大火煮沸后撇净浮沫，煮3-5分钟捞出，用温水冲洗干净。\n3.锅里倒油，锅润后将油倒出，放入羊排、姜片、葱段煸炒至香。随后加足量开水，大火烧开后转小火慢炖2小时。\n4.加入白萝卜块或胡萝卜块，再炖煮20分钟，最后加盐、白胡椒粉调味。‌‌最后撒上香菜，出锅。', '-注意焯水时‌不可盖锅盖‌，以便腥味挥发。‌‌\n-炖煮时加入白芷、山楂果（避免八角、桂皮），可有效中和膻味并软化肉质。‌‌\n-炖汤时‌必须用开水‌，并可在炒制羊排至微焦后再炖煮，使汤色更浓郁。‌‌', '2025-12-22 06:39:59', '2025-12-22 06:39:59');
INSERT INTO `nutritional_recipe` VALUES (1767532249799, '', '锅包肉', '锅包肉（英文名：Fried Pork in Scoop），原名锅爆肉，清光绪年间始创自哈尔滨道台府府尹杜学瀛厨师郑兴文之手。 [20]成菜后，色泽金黄，口味酸甜。\n锅包肉是为适应外宾口味，把咸鲜口味的“焦烧肉条”改成了一道酸甜口味的菜肴。通常将猪里脊肉切片腌入味，裹上炸浆，下锅炸至金黄色捞起，再下锅拌炒勾芡即成。\n2022年，哈尔滨锅包肉入选国家《地标美食名录》。', '东北菜', '940.2', '102.6', '28.0', '69.7', ' 猪里脊                    350g\n土豆淀粉 120g\n小葱【葱】 30g\n仔姜【嫩姜】 10g\n胡萝卜 20g\n', '白糖25g、白醋20g、生抽1勺、盐一小撮', '1.里脊肉切片[约3毫米厚度]，用刀背拍松，加一勺料酒，一撮盐，搅拌均匀，腌制10分钟。\n2.土豆淀粉加60g清水，调成糊状，加入腌制好的里脊肉片，让每一片里脊肉裹上。\n3.锅中热油（筷子冒小泡），中小火炸2分钟至微黄定型后捞出。‌‌\n4.锅中热油（油面冒烟），大火炸30秒至金黄酥脆，后捞出。‌‌\n5.锅留底油，炒香葱姜丝后放入胡萝卜丝翻炒，倒入糖醋汁【白糖、白醋、生抽、盐】大火煮至冒泡，加半勺水淀粉勾芡（汁能挂勺），然后立刻倒入肉片，大火翻炒10秒出锅。\n\n\n\n', '', '2026-01-04 13:10:50', '2026-01-08 07:04:10');
INSERT INTO `nutritional_recipe` VALUES (1767856515827, '', '粉蒸肉', '粉蒸肉，又称米粉肉，是中国传统菜肴，属赣菜系，发源于江西。其历史最早可追溯至屈原《楚辞》中“蕙肴蒸兮兰籍”的记载，清代袁枚在《随园食单》明确其为江西菜品。该菜以五花肉为主料，裹米粉蒸制而成，具有糯而清香、酥嫩不腻的特点，可添加香菇、莲藕、南瓜等辅料调味。\n传统做法以炒米粉裹肉蒸制，南昌地区保留菜叶垫底的古法工艺，重庆等地则采用榨辣椒调味。', '川菜', '2178.8', '39.3', '208.4', '47.9', ' 猪肉（肋排）软五花、猪夹心  500g\n甘薯（红心）【山芋、红薯】 200g\n黄姜 30g\n小葱【葱】 30g\n', '生抽、老抽、耗油、料酒、米粉', '1.五花肉切成薄片，清洗干净沥干水分后备用。\n2.切好的肉中加入：两勺生抽、半勺老抽、一勺料酒、半勺耗油，抓拌均匀腌制20分钟。\n3.腌好的肉中加入米粉【米粉能均匀的包裹肉片】，抓拌均匀后腌制10分钟。\n4.红薯【也可以换成南瓜、土豆等喜欢的食材】剥皮切块，铺在盘底，然后将腌制好的肉片均匀铺在上面。\n5.最后放入蒸锅，水开转小火蒸50分钟【高压锅20分钟】', '1.蒸的时间越长肉质口感会更软一些，正对老年人的吃食可以适当延长蒸煮时长。\n2.切记不要把水蒸干了。', '2026-01-08 07:15:16', '2026-01-08 07:17:50');
INSERT INTO `nutritional_recipe` VALUES (1767858172798, '', '梅菜扣肉', '梅菜扣肉（英文名：Pork with salted vegetable）是广东客家传统名菜，以五花肉、梅菜为主料，配以姜片、葱白、老抽等调料，成菜色泽酱红、咸鲜肥而不腻 [1] [8]。梅菜名称源于民间传说，相传卢姓娘子获梅姓仙女赠菜籽种植制成，惠州梅菜素有“惠州贡菜”雅称，因“苎萝西子十里绿，惠州梅菜一枝花”于2006年获“中国梅菜之乡”称号', '粤菜', '2035.9', '3.9', '207.9', '45.9', ' 猪肉（肋排）软五花、猪夹心  500g\n黄姜 30g\n小葱【葱】 10g\n', '老抽、生抽、料酒、花椒、胡椒粉、盐', '1.梅菜干提前侵泡，洗净拧干水分备用。\n2.五花肉冷水下锅，放料酒、花椒、姜片、盐，煮20分钟，后捞出备用，剩下的汤汁留着。\n3.猪皮抹上老抽，可用叉子搓几下，方便上色，锅中倒油，开小火，猪皮朝下煎3分钟左右，放入【步骤2】中的汤汁侵泡至起虎皮，捞出切片备用。\n4.五花肉中加入生抽、老抽、耗油、鸡精、白糖、胡椒粉，抓拌均匀，腌制10分钟。', '5.将腌制好的五花肉，皮朝下，一片片的摆好。\n6.锅中倒油，放入姜末炒香，倒入梅干菜、【步骤4】中剩下的料汁翻炒几下后铺在五花肉上。\n7.将摆好的五花肉放入蒸锅，水开转小火蒸60分钟。', '2026-01-08 07:42:53', '2026-01-08 07:54:34');
