INSERT INTO `nutritional_recipes` VALUES (1731033086605, '养胃食谱', '清淡饮食', '杂粮+蛋白+碳水', '苹果山药小米粥\n香菇炒菜心\n芙蓉蒸蛋', '无', '红薯饭\n清炒西兰花\n胡萝卜烧牛肉', '无', '莲子百合粥\n莴笋炒黑木耳\n荷兰豆藕片', '无', '脾胃虚', 1680851452956, '2024-11-08 10:31:27', '2024-11-08 10:31:27', '无');
