INSERT INTO `t_blog` VALUES (1678863756424, '博客概念', '博客是什么,类型有哪些 1. 个人博客,也就是网络上的个人博客,通常在一个人拥有独立 IP地址的互联网上以电子邮件形式向公众展示自己的生活、工作和爱好,主要面... 2. 商业博客,又称企业博客,是指专门为商业机构或企业提供个性化信息服务并进行网络营销的网站; 行业博客,又称行业信息博客、垂直行业博... 3. 社交网络、博客和 SNS网站都属于社交网络(Social Network)。 SNS网站的最大特色是具有社区性质,用户通过... ', '博客，仅音译，英文名为Blogger，为Web Log的混成词。其正式名称为网络日记；又音译为部落格或部落阁等，是社会媒体网络的一部分。是使用特定的软件，在网络上出版、发表和张贴个人文章的人，或者是一种通常由个人管理、不定期张贴新的文章的网站。博客上的文章通常以网页形式出现，并根据张贴时间，以倒序排列。通常具备RSS订阅功能。\n博客是继MSN、BBS、ICQ之后出现的第4种网络交流方式，现已受到大家的欢迎，是网络时代的个人“读者文摘”，是以超链接为入口的网络日记，它代表着新的生活、工作和学习方式。许多博客专注在特定的课题上提供评论或新闻，其他则被作为个人性的日记。一个典型的博客结合了文字、图像、其他博客或网站的链接及其它与主题相关的媒体，能够让读者以互动的方式留下意见，是许多博客的重要要素。大部分的博客内容以文字为主，但仍有一些博客专注在艺术、摄影、视频、音乐、播客等各种主题。', '/static/2024-01-23/BLOG.jpeg', '转载', b'00', b'00', b'01', '0', '1', '0', 1705980624172, 1680851452956, '[1705980662741, 1705980557620]', b'00', '2023-03-16 07:02:36', '2025-03-27 07:53:58', NULL, NULL);
INSERT INTO `t_blog` VALUES (1680859628760, '八重神子', '鸣神大社的大巫女、狐之血脉的延续者、「永恒」的眷属与友人', '鸣神大社的大巫女、狐之血脉的延续者、「永恒」的眷属与友人…以及，轻小说出版社「八重堂」的恐怖总编。\n\n不必追寻其中任何一面。每一面都是八重神子，每一面却也无法成为真正的她。\n\n各种姿态，都犹如镜子的碎片，映射出截然不同的她。因诸多身份包裹，她亦成为了一块被无数面御镜包围的宝钻。\n\n上百种面相，严肃或快活，悲悯或漠然。\n\n无人知晓真实，就像无人能轻易从秘林中找到一只与过客擦肩的仙狐。\n\n![1666794890983.png](1)\n「今夜的月光如此清亮，不做些什么真是浪费。随我一同去月下漫步吧，不许拒绝。」\n\n细究起来，八重神子的头衔竟与她的性情同样难测多变。\n\n出于各种目的试图搞清神子「真面目」的人，可以从天领奉行府一路排到「八重堂」门口，然而迄今为止，成功者依旧寥寥。\n\n——只需记得，她永远是那位「兼具智慧与美貌的八重神子大人」就好。\n「今夜的月光如此清亮，不做些什么真是浪费。随我一同去月下漫步吧，不许拒绝。」\n\n细究起来，八重神子的头衔竟与她的性情同样难测多变。\n\n出于各种目的试图搞清神子「真面目」的人，可以从天领奉行府一路排到「八重堂」门口，然而迄今为止，成功者依旧寥寥。\n\n——只需记得，她永远是那位「兼具智慧与美貌的八重神子大人」就好。\n「元素战技·野干役咒·杀生樱」\n\n八重神子迅速移动，并留下一株「杀生樱」。杀生樱可以间接性对周围的一名敌人降下落雷，造成雷元素伤害；附近存在其他的杀生樱时，将提升其位阶，提高上述攻击造成的伤害。\n\n杀生樱拥有3次可使用次数。最多同时存在3株杀生樱，杀生樱创造时的初始位阶为壹阶，阶级初始至多提升至叁阶。若创造的位置与已有的杀生樱距离过近，则会摧毁已有的杀生樱。\n「元素爆发·大密法·天狐显真」\n\n八重神子降下雷电，造成雷元素范围伤害。\n\n施放时，八重神子会解放附近的杀生樱，摧毁它们的形姿，化作天狐霆雷降下，造成雷元素范围伤害。每通过这种方式摧毁一株杀生樱，就能降下一道天狐霆雷。\n无人知晓真实，就像无人能轻易从秘林中找到一只与过客擦肩的仙狐。\n\n可若是狐狸注视着人…狐狸又将往何处去？', '/static/2023-04-07/1666794890983.png', '原创', b'01', b'01', b'01', '0', '53', '54', 1680859288073, 1700732037690, '[1680859324288]', b'00', '2023-04-08 09:27:09', '2023-11-29 06:32:46', NULL, NULL);
INSERT INTO `t_blog` VALUES (1680860116487, '纳西妲', '纳西妲，本名布耶尔，“尘世七执政”中的草之神，所罗门72柱中第10位，被须弥人给予“小吉祥草王”的爱称  。现今七神中最年轻的一位，自诞生起已五百年   。 纳西妲曾深居净善宫内，向来不受重视，也很少被人提及。她身负重任，哪怕目睹漆黑，经历孤独，也不曾停下脚步', '## 身份背景\n   许久前，草神创造了须弥雨林，又通过教令院将智慧赐予国民。她的美名无处不在，千万个故事，只为传唱她的事迹与美德而问世。在人民眼中，草神的存在更像是一种符号化的象征——因此，他们才能确信神明的庇护自古就存在于这片土地之上。城中至贤对草神崇拜备至，民众也坚定不移地追随其后。而影响诸多的“虚空”系统，则是”小吉祥草王”的耳与目。\n它给予她遍历人们喜怒哀乐的能力，令她听见看见一切，让她理解了赞美之外的声音。见闻越是拓展，她越明白自己必须不断学习。她唯有尽快成长，才能面对来自世界最深处的威胁。无法逃离，那是她无法回避的使命。即便没多少人对现状不满,纳西妲依旧坚定不移。她的顽强来源于信念,她比任何人都明白——在这里，她将是所有人的寄托与依靠\n## 相貌衣着\n纳西妲外表是一位年幼的女孩，有着一双尖耳朵。灰白色的长发扎成侧马尾，发尾有明显的绿色渐变色。纳西妲的虹膜是深绿色，而她的十字形瞳孔是浅绿色，周围有一圈深绿色的纹路。纳西妲身披绿色的披风，以及身穿白色花苞裙，裙表面上有着一条条金色纹路，内侧则是绿色。双腿没有衣物，脚上穿着白色踩脚袜。\n## 性格特点\n在纳西妲的观点中，万事万物都存在着相互联系，一切事物都可以指向“命运”   。纳西妲很喜欢使用比喻，她认为比喻是可以用已知知识来理解未知知识的奇妙工具  。虽然会很多大道理，但对常识却不怎么了解 。\n对比起全知全能的大慈树王，纳西妲自认还远远担不起“智慧之神”的名号，对国家的治理也是教令院更加驾轻就熟，她的存在并没有那么大的意义。所以她在净善宫的每一刻都不停在学习，希望尽快成长为一位合格的神明。虽然一直在观察人们，但对模仿一直很不擅长。', '/static/2025-12-24/8bdc9d65-f7d4-438c-b842-dcfa9723795e.png', '原创', b'01', b'01', b'01', '0', '0', '0', 1680859288073, 1680851452956, '[1680859324288]', b'00', '2023-04-08 09:35:16', '2025-12-24 13:03:33', NULL, NULL);
INSERT INTO `t_blog` VALUES (1705979964267, 'node.js安装踩坑记录', 'node安装记录', '一、修改全局模块下载路径 （下载 | Node.js 中文网 (nodejs.cn)）\n1.在Node下新建【node_global】及【node_cache】文件夹\n2.cmd输入：npm config set prefix \"D:\\Nodejs\\node_global\"\n  npm config set cache \"D:\\Nodejs\\node_cache\"\n3.将【用户变量】下的【Path】修改为【D:\\Nodejs\\node_global】，在【系统变量】下新建【NODE_PATH】【D:\\Nodejs\\node_global\\node_modules】，在【系统变量】下的【Path】新建添加node全局文件夹【D:\\Nodejs\\node_global】\n4.测试：npm install express -g\n5.若报错，是由于权限的原因，右击Nodejs文件夹->属性->安全，点击编辑，将所有权限都✔即可\n二、更换npm源为淘宝镜像\n1.查看初始npm源：npm config get registry\n2.更换镜像为淘宝镜像：npm config set registry https://registry.npm.taobao.org/\n三、全局安装基于淘宝源的cnpm\n1.全局安装基于淘宝源的cnpm：npm install -g cnpm --registry=https://registry.npm.taobao.org\n2.执行命令查看cnpm是否安装成功：cnpm -v', '/static/2024-01-23/nodes.jpeg', '原创', b'00', b'00', b'01', '0', '0', '0', 1678852528115, 1680851452956, '[1678852680689]', b'00', '2024-01-24 03:19:24', '2025-03-27 07:54:36', NULL, NULL);
INSERT INTO `t_blog` VALUES (1705981493568, 'GIT相关', 'GIT的一些常见问题', '## Q：git ssh 配置以及公钥\n#### 一、查看git配置：git config --list\n#### 二、配置用户和邮箱\ngit config --global user.nme \"用户名\"\ngit config --global user.email \"邮箱\"\n#### 三、生成本地SSH密钥，一直Enter到结束：ssh-keygen -t rsa -C \'邮箱\'\n#### 四、查看密钥：cat ~/.ssh/id_rsa.pub\n#### 五、将密钥添加到github\n## Q：github相关命令\n1.克隆GitHub项目到本地：git clone SSH地址\n2.添加项目文件：git add .\n3.输入提交信息：git commit -m \"提交信息\"\n4.上传：git push -u origin mian\n## Q：github无法上传更新代码\n1.拉取最新更新内容：git pull --rebase origin master\n2.上传：git push origin master', '/static/2024-01-23/GIT.jpg', '原创', b'01', b'01', b'01', '0', '32', '0', 1678852528115, 1680851452956, '[1705981102799, 1705980662741]', b'00', '2024-01-24 03:44:54', '2025-05-30 11:55:24', NULL, NULL);
INSERT INTO `t_blog` VALUES (1705981803285, '个人账号密码', '杨华杰的各种账号密码记录-备忘', '小米账号:2180219485          密码:yang554330\n秒滴账号:15723084621        密码:yangHUA123#\n\n网易邮箱：yhj1251120808@163.com  yang554330\n\nCSDN账号：15723084621   yanghuajie1251120808\n\nGitHub账号：\nyang554    yang554330\nyang554-gt     yang554330\n\nXIAOI账号：yangSir123		yang123456\n图灵机器人：15723084621	yang123456\n\n淘宝沙箱帐号：\n    商家帐号：nhandc2926@sandbox.com\n    密码：111111\n    \n    买家账号：otmprx4986@sandbox.com\n    密码：111111 \n    \n    PID : 2088122710074521\n    \n    APPID : 2016091300500798\n    \n    支付宝网关 ： https://openapi.alipaydev.com/gateway.do\n云服务器登录账号：root 密码：yanghj123!@#\n\n中国大陆区：steam账户名jmyfl05879密码wzei87295G邮箱801ctldj0@230.wwkesi.club邮箱密码gg1gw40h邮箱登录网址：http://mail.wwkesi.club/\n\n卡号：中国大陆区：steam账户名jmyfl05879密码Yang554330邮箱801ctldj0@230.wwkesi.club邮箱密码Yang554330邮箱登录网址：http://mail.wwkesi.club/', '/static/2024-01-23/user-pad.png', '原创', b'00', b'00', b'01', '0', '0', '0', 1705981684647, 1680851452956, '[1705981691917]', b'00', '2024-01-24 03:50:03', '2024-03-22 08:23:19', NULL, NULL);
INSERT INTO `t_blog` VALUES (1706000333103, 'VUE常见概念', 'Vue (发音为 /vjuː/，类似 view) 是一款用于构建用户界面的 JavaScript 框架。它基于标准 HTML、CSS 和 JavaScript 构建，并提供了一套声明式的、组件化的编程模型，帮助你高效地开发用户界面。无论是简单还是复杂的界面，Vue 都可以胜任。', '### 1. 什么是MVVM?\n	在MVVM框架下 视图和模型是不能直接通信 的，只能通过ViewModel进行交互，它能够监\n	听到数据的变化，然后通知视图进行自动更新，而当用户操作视图时，VM也能监听到视图\n	的变化，然后通知数据做相应改动，这实际上就实现了数据的 双向绑定 。并且V和VM可以进行通信。\n	Model（模型）\n	    模型是指代表真实状态内容的领域模型（面向对象），或指代表内容的数据访问层（以数据为中心）。\n	View（视图）\n	    就像在MVC和MVP模式中一样，视图是用户在屏幕上看到的结构、布局和外观（UI）。\n	ViewModel（视图模型）\n	    视图模型是暴露公共属性和命令的视图的抽象。MVVM没有MVC模式的控制器，也没有MVP模式的\n	presenter,有的是一个绑定器。在视图模型中，绑定器在视图和数据绑定器之间进行通信。\n	优点:\n	低耦合 :View可以独立于Model变化和修改,一个ViewModel可以绑定到不同的View上,当View变化\n	的时候Model可以不变,当Model变化的时候View也可以不变。\n	可重用性 : 可以把一些视图逻辑放在一个ViewModel里面,让很多View重用这段视图逻辑。\n	独立开发 : 开发人员可以专注于业务逻辑和数据的开发,设计人员可以专注于页面的设计。\n### 2. 什么是MVC?\n	MVC是应用最广泛的软件架构之一,一般MVC分为:Model(模型),View(视图),Controller(控制器)。 \n	这主要是基于分层的目的,让彼此的职责分开.View一般用过Controller来和Model进行联系。			 \n	Controller是Model和View的协调者,View和Model不直接联系。基本都是单向联系。M和V指的意思和\n	MVVM中的M和V意思一样。C即Controller指的是页面业务逻辑。MVC是单向通信。也就是View跟Model，\n	必须通过Controller来承上启下。\n	Model（模型）表示应用程序核心（如数据库）。\n	View（视图）显示效果（HTML页面）。\n	Controller（控制器）处理输入（业务逻辑）。\n	MVC 模式同时提供了对 HTML、CSS 和 JavaScript 的完全控制。\n	Model（模型）是应用程序中用于处理应用程序数据逻辑的部分。 　　\n	通常模型对象负责在数据库中存取数据。\n	View（视图）是应用程序中处理数据显示的部分。 　\n	通常视图是依据模型数据创建的。\n	Controller（控制器）是应用程序中处理用户交互的部分。 　　\n	通常控制器负责从视图读取数据，控制用户输入，并向模型发送数据。\n	优点:\n	    低耦合\n	    重用性高\n	    生命周期成本低\n	    部署快\n	    可维护性高\n	    有利软件工程化管理', '/static/2025-05-28/f3d596b4-9bf0-45e6-b086-59ed69a584a6.jpg', '转载', b'01', b'01', b'01', '5', '1', '1', 1678852528115, 1680851452956, '[1678852680689]', b'00', '2024-01-24 08:58:53', '2025-05-29 09:42:04', NULL, NULL);
INSERT INTO `t_blog` VALUES (1708224918901, '前端理论题', '集合前端技术栈常见题型', '### Q：ES5和ES6继承有什么区别\nA：ES5是通过构造函数实现，ES6是通过extend继承。', '/static/2024-02-18/前端png.jpg', '原创', b'01', b'01', b'00', '2', '0', '0', 1678852528115, 1680851452956, '[1705981691917, 1705981102799, 1705980662741]', b'00', '2024-02-19 02:55:19', '2025-01-10 07:51:48', NULL, NULL);
INSERT INTO `t_blog` VALUES (1708414578236, 'vue-cli安装失败', 'npm的证书失效了，它不再支持自签名证书 ', '### 一、报错情况\n```language\nnpm ERR! code CERT_HAS_EXPIRED\nnpm ERR! errno CERT_HAS_EXPIRED\nnpm ERR! request to https://registry.npm.taobao.org/vue-cli failed, reason: certificate has expired\n```\n### 二、解决方案\n1. 查看自己的下载源：npm config get registry，\n   发现我们之前配置了下载镜像源为https开头的：https://registry.npm.taobao.org/\n2. 执行命令清除npm缓存：npm cache clean --force\n3. 执行命令取消ssl验证：npm config set strict-ssl false\n4. 再次执行npm install ***，还不行可以尝试设置你的npm镜像源为http开头的，不使用https：npm config set registry http://registry.npm.taobao.org\n', '/static/2024-10-30/ba402601-d444-44b6-b32a-fcc4366a1e7c.png', '原创', b'01', b'01', b'01', '100008', '1284', '66', 1678852528115, 1680851452956, '[1678852680689]', b'00', '2024-02-21 07:36:18', '2024-02-21 07:37:54', NULL, NULL);
INSERT INTO `t_blog` VALUES (1730080351642, '咸鱼之王', '满级梦魇水晶属性详情', '‌攻击水晶‌：攻击+11200，攻击+31%\n‌精准水晶‌：攻击+6600，精准+21%，攻击+18%\n‌破甲水晶‌：攻击+6600，破甲+30%，攻击+18%\n‌暴击水晶‌：暴击+15%，爆伤+54%，攻击+4%\n‌技能伤害水晶‌：精准+23%，技能伤害+50%\n‌减伤水晶‌：攻击+6600，减伤+18%，血量+22%\n‌生命水晶‌：血量+12.8万，血量+37%\n‌格挡水晶‌：格挡+18%，血量+24%\n‌生命暴击水晶‌：暴击+15%，血量+24%\n‌速度水晶‌：血量+23%，速度+200\n‌免控水晶‌：血量+12.8万，血量+33%，免控+12%‌12', '/static/2025-05-29/8d86686e-9f84-4ce6-b993-6f1a1849c80f.png', '原创', b'01', b'01', b'01', '34', '1123', '1', 1680859288073, 1680851452956, '[1705981691917]', b'00', '2024-10-29 01:52:32', '2025-05-30 11:55:38', NULL, NULL);
