INSERT INTO `t_blog` VALUES (1748243607714, 'Windows 系统下安装 RabbitMQ', 'RabbitMQ 是一个流行的开源消息代理，采用 AMQP（高级消息队列协议）标准。它允许应用程序之间以异步方式交换数据，确保消息的可靠性和灵活性。RabbitMQ 适用于各种场景，如微服务架构、异步处理、工作队列等。', '在安装 RabbitMQ 之前，请确保您的 Windows 系统符合以下要求：\n\n操作系统：Windows 7、8、10 或更高版本\n架构：x64（64 位）\n此外，RabbitMQ 依赖于 Erlang 环境，因此需要先安装 Erlang。\n#### 一、下载并安装 Erlang\n1、访问 Erlang 官方下载页面：https://www.erlang.org/downloads\n2、选择适合您系统的安装程序，通常为 Windows 64-bit Installer，选择匹配的版本。\n3、运行安装程序，按照提示完成安装，默认 next 即可。\n#### 二、下载并安装 RabbitMQ\n1、访问 RabbitMQ 官方下载页面：https://www.rabbitmq.com/download.html\n2、下载适用于 Windows 的安装程序，选择合适的版本，例如最新的 rabbitmq-server-4.0.9.exe。\n3、运行安装程序，按照提示完成安装，可以自定义安装路径。\n#### 三、配置环境变量\n1、添加 Erlang 和 RabbitMQ 的安装路径，例如：\nD:\\Program Files\\Erlang\\bin\nD:\\Program Files\\RabbitMQ Server\\rabbitmq_server-4.0.7\\sbin\n2、验证安装\n打开命令提示符，输入 erl，如果显示 Erlang 的版本信息，则表示 Erlang 安装成功。\n输入 rabbitmqctl status，如果显示 RabbitMQ 的状态信息，则表示 RabbitMQ 安装成功。\n#### 四、启用 RabbitMQ 管理插件\n进入安装目录的 /sbin 目录下，在命令提示符中输入：rabbitmq-plugins enable rabbitmq_management\n#### 五、重新启动 RabbitMQ 服务\n#### 六、访问管理界面\n在浏览器中输入 http://localhost:15672/\n默认用户名：guest\n默认密码：guest\n注意：==出于安全考虑，默认的 guest 用户只能本地访问，建议在生产环境中创建新的用户并赋予相应权限。==\n\n[转载地址](转载地址)：https://blog.csdn.net/qq_41929714/article/details/146152629', '/static/2025-05-28/d0c7d5e7-406f-4875-81a9-7f68ee1393e8.jpeg', '原创', b'01', b'01', b'01', '29', '2', '1', 1678852528115, 1680851452956, '[1678852629023, 1678852675943]', b'00', '2025-05-27 07:13:28', '2025-12-24 14:22:12', NULL, NULL);
