INSERT INTO `t_blog` VALUES (1765111710713, 'linux更新前后端', '在linux下更新spring boot + vue + MySQL 前后端分离项目', '## 后端更新\n### 1. 进入后端项目目录\ncd /home/yanghj/backend\n### 2. 备份当前运行的 JAR 文件\nsudo cp blog-0.0.1-SNAPSHOT.jar blog-0.0.1-SNAPSHOT.jar.backup.$(date +%Y%m%d%H%M%S)\n### 3. 上传新的 JAR 文件（从本地）\n### 4. 设置权限\nsudo chown yanghj:yanghj blog-0.0.1-SNAPSHOT.jar\nchmod 755 blog-0.0.1-SNAPSHOT.jar\n### 5. 重启 Spring Boot 服务\nsudo systemctl restart yanghj-app\n### 6. 检查服务状态\nsudo systemctl status yanghj-app\n### 7. 查看启动日志\nsudo journalctl -u yanghj-app -n 20 -f\n\n## 前端更新\n### 1. 进入前端目录\ncd /home/yanghj/frontend\n### 2. 备份当前版本\nsudo cp -r dist/ dist.backup.$(date +%Y%m%d%H%M%S)\n### 3. 上传新的 dist 目录内容（从本地构建）\n### 4. 设置权限\nsudo chown -R www-data:www-data dist/\nsudo chmod -R 755 dist/\n### 5. 重新加载 Nginx\nsudo systemctl reload nginx\n### 6. 检查 Nginx 状态\nsudo systemctl status nginx\n\n## 数据库更新\n### 1. 备份当前数据库\nmysqldump -u yanghj -p yanghj_blog > /home/yanghj/backup/yanghj_blog_$(date +%Y%m%d%H%M%S).sql\n### 2. 只导入新增的数据表或结构变更\nmysql -u yanghj -p yanghj_blog < /path/to/db.sql\n### 3. 验证导入结果\nmysql -u yanghj -p -e \"USE yang-blog; \nSHOW TABLES;\"', '', '原创', b'01', b'01', b'01', '0', '0', '0', 1678852528115, 1680851452956, '[1765111889167, 1678852680689, 1678852675943]', b'00', '2025-12-07 12:48:31', '2025-12-07 12:51:52', NULL, NULL);
INSERT INTO `t_blog` VALUES (1765112159387, 'MYSQL主从数据同步', '主数据库是在云上的linux系统，从数据库是在本地的windows系统上', '### 查询系统用户\n	SELECT User, Host FROM mysql.user;\n### 创建复制用户\nCREATE USER \'user_cp\'@\'%\' IDENTIFIED BY \'123456\';\nGRANT REPLICATION SLAVE ON *.* TO \'user_cp\'@\'%\';\nFLUSH PRIVILEGES;\n### 记录 File 和 Position\nSHOW MASTER STATUS;\n### 使用mysqldump导出全量数据（在云服务器执行）\ndocker exec mysql mysqldump -uroot  -p123456  --single-transaction --source-data=2  --all-databases > yang-blog.sql\n### 使用MySQL命令行客户端\nCHANGE MASTER TO\n  MASTER_HOST = \'118.25.110.52\',\n  MASTER_USER = \'user_cp\',\n  MASTER_PASSWORD = \'123456\',\n  MASTER_PORT = 3306,\n  MASTER_LOG_FILE = \'mysql-bin.000004\',  -- 替换为主库状态中的File\n  MASTER_LOG_POS = 157;                 -- 替换为主库状态中的Position\nSTART SLAVE;\n### 停止同步\nSTOP SLAVE;\n### 重启同步\nRESET SLAVE;\n### 验证复制状态\nSHOW SLAVE STATUS\\G;  ', '', '原创', b'01', b'01', b'01', '0', '0', '0', 1678852528115, 1680851452956, '[1765111889167]', b'00', '2025-12-07 12:55:59', '2025-12-10 07:05:08', NULL, NULL);
INSERT INTO `t_blog` VALUES (1765350526332, 'Docker容器部署', 'Docker部署Java spring boot前后端分离项目', '### 目录结构\nyour-project/\n├── docker-compose.yml             # 核心编排文件\n├── backend/                       # Spring Boot 后端\n│   ├── Dockerfile                 # 后端镜像构建文件\n│   ├── src/                       # Java 源代码\n│   ├── pom.xml                    # Maven 配置文件\n│   └── ...                        # 其他后端文件\n├── frontend/                      # Vue 前端\n│   ├── Dockerfile                 # 前端镜像构建文件\n│   ├── nginx.conf                 # Nginx 配置文件\n│   ├── src/                       # Vue 源代码\n│   ├── public/                    # 静态资源\n│   ├── package.json               # Node.js 依赖\n│   └── ...                        # 其他前端文件\n├── mysql/                         # MySQL 配置\n│   └── init.sql                   # 数据库初始化脚本\n├── redis/                         # Redis 配置\n│   └── redis.conf                 # Redis 配置文件\n└── rabbitmq/                      # RabbitMQ 配置\n    └── definitions.json           # 队列和用户定义\n\n### 上传文件到项目\n前后端的Dockerfile、后端jar包、前端dist文件、sql文件\n### 制作镜像\ndocker build -t blog-api:1.0 .\n### 配置私有网络\ndocker network create yanghj\n### 查看镜像\ndocker image ls\n### 配置redis\ndocker run --name redis -p 6379:6379 -d redis:latest\n### 配置mysql\ndocker run --name mysql -p 3306:3306 -d  mysql:8\n### 相关操作命令\n查看运行容器：docker ps\n删除容器：docker rm -f 容器名字或ID\n查询端口：sudo netstat -tuln | grep 6379\n不用缓存，强制重构：docker-compose build --no-cache frontend\n重启容器并应用新镜像：docker-compose up -d --force-recreate frontend\n进入容器：docker exec -it backend sh\n批量删除所有悬空镜像：docker image prune\n手动删除单个镜像：docker rmi <镜像ID>\n查看所有悬空镜像:docker images -f \"dangling=true\"\n更改目录所有权：sudo chown -R 999:999 mysql-logs mysql-conf mysql-data\n更改目录权限：sudo chmod -R 755 mysql-logs mysql-conf mysql-data\n查看防火墙状态：sudo ufw status\n开放端口：sudo ufw allow 8080/tcp\n查看容器端口映射：docker inspect mysql | grep HostPort\n查找使用该卷的容器‌：docker ps -a --filter volume=blog_mysql_data\n停止并删除关联容器‌：docker stop <container_id> && docker rm <container_id>', '', '原创', b'01', b'01', b'01', '1', '0', '0', 1678852528115, 1680851452956, '[1765111889167, 1678852675943]', b'00', '2025-12-10 07:08:46', '2025-12-10 07:17:15', NULL, NULL);
INSERT INTO `t_blog` VALUES (1765373760318, '厕所一下', '头晕', '特鲁姆普咯\n```\n//你好使劲\n```\n', '', '原创', b'01', b'01', b'01', '0', '0', '0', 1678852586349, 1680851452956, '[1705981691917, 1765111889167]', b'01', '2025-12-10 13:36:00', '2025-12-10 13:36:21', NULL, NULL);
INSERT INTO `t_blog` VALUES (1766584945296, 'JVM与性能调优', 'JVM与性能调优', '问题：应用运行一段时间后频繁Full GC，监控显示老年代持续增长\npublic class CacheManager {\n    private static Map<String, Object> cache = new HashMap<>();\n    \n    public void addToCache(String key, Object value) {\n        cache.put(key, value); // 对象永远不会被释放\n    }\n}\n解决方案：\n使用WeakHashMap或SoftReference\n设置过期时间定期清理\n使用工具定位：jmap -histo:live PID查看对象数量\n添加JVM参数监控：-XX:+HeapDumpOnOutOfMemoryError\n\n问题：线上服务器CPU持续100%，应用响应缓慢\n排查步骤：\ntop -Hp [PID] 找到高CPU线程\njstack [PID] 查看线程堆栈\n使用Arthas：thread -n 3 查看最忙线程\n优化方案：添加sleep、使用线程池控制并发、避免过度轮询\n\n问题：应用抛出java.lang.OutOfMemoryError: Java heap space\n解决方案：\n增大堆内存：-Xmx4g -Xms4g\n优化对象创建：使用对象池、延迟加载\n分页处理大数据\n使用NIO的DirectBuffer减少堆内内存使用\n\n问题：线程池任务堆积，响应超时\n解决方案：\nThreadPoolExecutor executor = new ThreadPoolExecutor(\n    10, 50, 60L, TimeUnit.SECONDS,\n    new ArrayBlockingQueue<>(100),  // 有界队列\n    new ThreadPoolExecutor.CallerRunsPolicy()  // 拒绝策略\n);\n\n问题：新生代GC频繁，每次GC时间不长但次数多\n优化方案：\n调整新生代比例：-XX:NewRatio=2（新生代:老年代=1:2）\n调整Eden/Survivor：-XX:SurvivorRatio=8\n使用G1GC：-XX:+UseG1GC -XX:MaxGCPauseMillis=200\n开启GC日志：-Xloggc:/path/to/gc.log -XX:+PrintGCDetails\n\n问题：类加载问题java.lang.ClassNotFoundException  /  NoClassDefFoundError\n解决方案：\nMaven排除冲突：<exclusions>\n使用mvn dependency:tree分析依赖\n自定义类加载器时确保父类委托机制\n检查MANIFEST.MF中的Class-Path\n\n问题：堆内存正常但物理内存持续增长\n排查：\nNMT监控：-XX:NativeMemoryTracking=detail\n使用命令：jcmd [PID] VM.native_memory summary\n使用-XX:MaxDirectMemorySize限制堆外内存\n确保DirectBuffer及时清理或使用池化', '', '原创', b'01', b'01', b'01', '4', '0', '0', 1678852528115, 1680851452956, '[1678852675943, 1678852629023]', b'00', '2025-12-24 14:02:25', '2025-12-24 14:08:54', NULL, NULL);
INSERT INTO `t_blog` VALUES (1766585687953, '面试反问', '遇到辣鸡公司或者态度不好的公司，直接反问回去', '1.贵公司薪资待遇怎么样，工资发放日是什么时候，是税前还是税后，有无年终奖，绩效考核有无，有的话什么标准，周期是多长\n2.有无试用期，试用期薪资怎么算，有无考核\n3.工作时间，上下班时间,双休还是单双休，法定节假日怎么休，加班是调休还是有加班费，忘打卡，迟到,请假等怎么扣钱，是否有带薪年假,怎么休\n4.合同情况，入职合同什么时候签（劳动合同应在1个月以内) 合同工资是否按照实际工资签订 合同签几年，是否有竞业限制\n6.工作情况，入职的部门负责什么工作，团队有多少人，怎么分工，工作地点在哪,是否外派，是否出差,出差频率\n7.五险一金缴纳情况，五险一金缴纳时间，社保交几档，公积金缴纳比例，其它福利（年假,体检,班车)', '', '原创', b'01', b'01', b'01', '0', '0', '0', 1766585752228, 1680851452956, '[1705981691917]', b'00', '2025-12-24 14:14:48', '2025-12-24 14:17:46', NULL, NULL);
INSERT INTO `t_blog` VALUES (1766586094410, '有意思的话', '有趣儿', '这个世界像一条深深的河流，走向不清楚，带着记忆与未知的情绪，和流浪的波纹，不停地淌过。', '', '原创', b'01', b'01', b'01', '0', '0', '0', 1766585752228, 1680851452956, '[1705981691917]', b'00', '2025-12-24 14:21:34', NULL, NULL, NULL);
INSERT INTO `t_blog` VALUES (1766586333655, 'JAVA面试题-基础篇', '常见面试题', 'Spring IOC/AOP 原理？\nIOC： 容器管理Bean生命周期，通过DI解耦。举例：@Autowired 自动注入依赖。\nAOP： 动态代理（JDK/CGLib）实现切面，用于日志/事务。举例：@Transactional 注解如何通过AOP开启事务。\n\nSpring MVC 工作流程？\n请求 → DispatcherServlet → 调用 HandlerMapping 找Controller → 执行方法 → ViewResolver 解析视图 → 返回响应。提拦截器(Interceptor)在流程中的作用（如权限校验）。\n\nMyBatis 一级/二级缓存区别？\n一级缓存： SqlSession级别，默认开启，相同SQL重复查询直接读缓存。\n二级缓存： Mapper级别，需手动配置，跨Session共享（注意脏读问题）。\n\n#{}和${}的区别？如何防SQL注入？\n#{} 预编译（安全），${} 字符串拼接（有注入风险）。\n防注入： 永远用#{}；禁用${}拼接用户输入；用MyBatis的<where>标签动态SQL。\n\nMySQL索引失效场景？\n未遵循最左前缀原则	WHERE a=1 OR b=2 (仅a有索引)	解决：改用UNION\n对索引列进行函数操作：WHERE YEAR(create_time)=2023	解决：改为范围查询\n隐式类型转换	WHERE phone=13800138000 (phone为varchar)	解决：统一类型\n%开头的LIKE	WHERE name LIKE \'%abc\'	解决：使用全文索引\n举例： 项目中发现某查询慢，用EXPLAIN发现索引失效，改用覆盖索引解决。\n', '', '原创', b'01', b'01', b'01', '0', '0', '0', 1678852275997, 1680851452956, '[1678852675943, 1678852629023]', b'00', '2025-12-24 14:25:34', NULL, NULL, NULL);
INSERT INTO `t_blog` VALUES (1766995638154, '肉类去腥', '各种肉类去腥方法', '• 鸡、鸭、鹅：使用白芷、良姜、草果这三种香料，尤其是草果，能让其腥味瞬间消失。\n\n• 猪肉：需用八角、桂皮、小茴香来去腥，同时少放丁香、肉桂、砂仁，可提升风味。\n\n• 牛肉：推荐“陈皮肉桂卤牛肉”，多放陈皮和肉桂，白芷、良姜、桂皮、八角可少放，多加香叶和肉蔻，卤出的牛肉风味更佳。\n\n• 羊肉：煮羊汤时加白芷，还可搭配花椒、白胡椒、香菜籽和小茴香，能让羊汤和羊肉香味十足。', '', '原创', b'01', b'01', b'01', '0', '0', '0', 1678852574553, 1680851452956, '[1766995674393]', b'00', '2025-12-29 08:07:18', '2025-12-29 08:08:35', NULL, NULL);
INSERT INTO `t_blog` VALUES (1767849753312, 'MYSQL数据库常用操作指令', '常用操作指令', '登录数据库：mysql -u root -p;\n查询系统用户：SELECT User, Host FROM mysql.user;\n查询所有数据库：SHOW databases;\n查询用户的认证插件：SELECT user, host, plugin FROM mysql.user WHERE user = \'username\';\n选择数据库：USE database_name;\n创建账号：CREATE USER \'username\'@\'host\' IDENTIFIED BY \'password\';\n给账号赋予所有权限：GRANT ALL PRIVILEGES ON database_name.* TO \'username\'@\'host\';\n指定权限：GRANT SELECT, INSERT, UPDATE ON `database_name`.* TO \'username\'@\'host\';\n权限更改刷新：FLUSH PRIVILEGES;\n查看数据库版本：SELECT VERSION();\n修改账号密码：ALTER USER \'yang_repl\'@\'%\' IDENTIFIED BY \'123456\';', '', '原创', b'01', b'01', b'01', '0', '1', '0', 1765111820433, 1680851452956, '[1765111889167, 1678852675943]', b'00', '2026-01-08 05:22:33', '2026-01-08 05:58:33', NULL, NULL);
